NEW="$TEMP/claude/D--Dev-AI-agents/1679de7f-3726-40d2-993a-fb1b84d51785/scratchpad/judge"; OLD="$TEMP/claude/D--Dev-AI-agents/e2bbc4b8-4b81-43db-a3f5-2aa3501fb64b/scratchpad/judge"; mkdir -p "$NEW" && cp "$OLD"/*.py "$OLD"/S*.md "$NEW"/ && cp "$OLD/../judge-key.txt" "$NEW/../" && cat > "$NEW/approvals.py" <<'EOF'
import json, glob, os, re, sys
root = os.path.expanduser("~/.claude/projects/D--Dev-AI-agents")
ok = re.compile(r"^\s*(да|ок|ok|согласен|делай|давай|land it|yes|go|верно|принимаю|отлично|хорошо|годится|правь)\b", re.I)
def text_of(msg):
    c = msg.get("content")
    if isinstance(c, str): return c
    return "\n".join(p["text"] for p in c or [] if isinstance(p, dict) and p.get("type") == "text")
rows = []
for f in glob.glob(root + "/*.jsonl"):
    last = None
    for i, line in enumerate(open(f, encoding="utf-8", errors="replace")):
        try: e = json.loads(line)
        except Exception: continue
        if "message" not in e: continue
        t = text_of(e["message"]).strip()
        if not t: continue
        if e.get("type") == "assistant" and len(t) > 600: last = (i, t, e.get("timestamp",""))
        elif e.get("type") == "user" and "system-reminder" not in t[:40] and not t.startswith("<"):
            if last and ok.search(t) and len(t) < 120 and e.get("timestamp","") >= "2026-09-28":
                rows.append((last[2][:16], os.path.basename(f)[:8], last[0], i, t[:50].replace("\n"," "), last[1][:150].replace("\n"," ")))
            last = None
seen=set()
for r in sorted(rows):
    k=(r[0],r[4])
    if k in seen: continue
    seen.add(k); print(*r, sep=" | ")
EOF
cd "$NEW" && PYTHONIOENCODING=utf-8 uv run --offline --no-project python approvals.py | wc -l
